    ('efc6493b-a5c3-5b71-ac25-181b5fb94074'::uuid, 'Quiz — Quand la maison et la famille s’effondrent ensemble', 'Français', '4e', 'Une nouvelle fantastique : « La Chute de la maison Usher » d’Edgar Allan Poe', 'ce72b0b3-6b46-5a50-a3c2-9bc221b8d37b'::uuid),
