    ('4266b09c-f867-5d4a-b96a-a99c8993c624'::uuid, 'Quiz — Reconnaître un discours qui veut faire penser', 'Français', '4e', 'Étude de textes et documents produits à des fins de propagande', '7e4e1113-609a-545a-a889-d3faa6e719d3'::uuid),
