    ('c630a319-c461-579a-a74f-1ba4cf2338ad'::uuid, 'Quiz — Un décor qui devient un personnage', 'Français', '4e', 'La ville comme sujet de roman', 'b79cd4cc-588a-52f2-b017-a33ea4678e2c'::uuid),
    ('075ce4d2-072d-5d6c-90e2-2cb9d643b3a3'::uuid, 'Quiz — De la laideur, faire un poème', 'Français', '4e', 'La ville comme objet poétique', '15457769-8d94-551f-a753-e9fd3c178022'::uuid),
    ('f9a12b39-2235-541e-9d4c-9282f050b100'::uuid, 'Quiz — Le crime a besoin d’une foule', 'Français', '4e', 'L’importance de la ville dans le roman policier', '4b43250c-f18f-5338-a266-3b2326f892f3'::uuid),
    ('97bcdad8-2a45-5017-819b-7270ddffbacd'::uuid, 'Quiz — Cadrer la ville, c’est déjà la raconter', 'Français', '4e', 'La ville dans la photographie, les films et la bande-dessinée', 'a8273617-e430-5768-9177-fd7caa56b0ba'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
